editorial:
For each right prefix, deque indices increase and their prefix sums strictly increase. Pop the front while it gives a qualifying interval. Any later endpoint would only make an interval starting there longer. Pop the back while its prefix is at least the current prefix. The new index is later and has an equal or smaller prefix, so it is always at least as good for a future endpoint. Push the current index. Each index enters and leaves once, giving O(n) time and space.
~~~
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n; long long target; cin >> n >> target;
    vector<long long> prefix(n + 1);
    for (int i = 1; i <= n; ++i) {
        long long x; cin >> x;
        prefix[i] = prefix[i - 1] + x;
    }
    deque<int> candidates;
    int best = n + 1;
    for (int r = 0; r <= n; ++r) {
        while (!candidates.empty() && prefix[r] - prefix[candidates.front()] >= target) {
            best = min(best, r - candidates.front());
            candidates.pop_front();
        }
        while (!candidates.empty() && prefix[candidates.back()] >= prefix[r])
            candidates.pop_back();
        candidates.push_back(r);
    }
    cout << (best <= n ? best : 0) << '\n';
}
